# Build an Agent with LangGraph: tiny workflow decision check.
case = {
    "has_evidence": True,
    "risk_score": 2,
    "needs_human": False,
}

def next_step(case):
    if not case["has_evidence"]:
        return "retrieve evidence"
    if case["risk_score"] >= 3 or case["needs_human"]:
        return "human review"
    return "draft answer"

print(next_step(case))
case["risk_score"] = 3
print(next_step(case))
